const menuResponse = $('Get current CRM menus').first().json;
const roomTypeResponse = $('Get current CRM room types').first().json;
const roomTypes = Array.isArray(roomTypeResponse.data) ? roomTypeResponse.data.filter((room) => room.isActive !== false).map(({ _id, name, baseRate, totalRooms, maxGuestsPerRoom, description, amenities }) => ({ roomTypeId: _id, name, nightlyRate: baseRate, totalRooms, maxGuestsPerRoom, description, amenities })) : [];
const menus = Array.isArray(menuResponse.data) ? menuResponse.data : [];
const conciseMenus = menus.filter((menu) => menu.isActive !== false).map((menu) => ({
  category: menu.category, title: menu.title, subtitle: menu.subtitle, badge: menu.badge, closingLine: menu.closingLine,
  price: menu.price, priceNote: menu.priceNote, menuTimeSlots: menu.menuTimeSlots || [], menuSections: menu.menuSections || [], roomCheckInTime: menu.roomCheckInTime || "", roomCheckOutTime: menu.roomCheckOutTime || "", roomStayDurationHours: menu.roomStayDurationHours || null, hotelInfo: menu.hotelInfo || {},
  description: menu.description, dishes: menu.dishes || [], weddingPackages: (menu.weddingPackages || []).filter((item) => item.isActive !== false), grandestOffer: menu.grandestOffer?.isActive === false ? null : (menu.grandestOffer || null), corporatePackages: (menu.corporatePackages || []).filter((item) => item.isActive !== false), corporateMeals: menu.corporateMeals || [], corporateMenuPreferences: menu.corporateMenuPreferences || [], corporateTaxPercent: menu.corporateTaxPercent, weddingTaxPercent: menu.weddingTaxPercent,
  weddingVenues: menu.weddingVenues || [], weddingSaladOptions: menu.weddingSaladOptions || [], weddingDessertOptions: menu.weddingDessertOptions || [], extraPrices: menu.extraPrices || [],
  media: { imageUrls: menu.media?.imageUrls || [], pdfUrls: menu.media?.pdfUrls || [], videoUrl: menu.media?.videoUrl || "", voiceNoteUrl: menu.media?.voiceNoteUrl || "" },
  activeOffers: (menu.activeOffers || []).map(({ title, description, discountText }) => ({ title, description, discountText })),
}));
const closureResponse = $input.first().json;
const closureData = closureResponse.data || {};
const closures = Array.isArray(closureData.closures) ? closureData.closures : [];
const closureContext = JSON.stringify({
  currentDateInPakistan: closureData.today || 'Unknown',
  priorityInstruction: 'Check these closures before greeting or replying about availability/booking. If today is closed, tell the customer the exact reason immediately. Never promise or create a booking on a listed closed date.',
  closures: closures.map(({ date, reason }) => ({ date, reason })),
});
const source = $('Edit Fields3').first().json;
return [{ json: { ...source, menuContext: JSON.stringify(conciseMenus), roomTypesContext: JSON.stringify(roomTypes), closureContext } }];

const raw = $input.first().json.output;

// Strip markdown code block wrapper (```json ... ```)
const cleaned = raw.replace(/```json\n?/g, '').replace(/```/g, '').trim();

const booking = JSON.parse(cleaned);

return [{ json: booking }];

const booking = $input.first().json;
const order = booking.order || {};
const packageName = String(order.package || '').trim();
let category = String(order.category || '').trim();
if (!category) {
if (/hi[\s-]?tea|hitea/i.test(packageName)) category = 'Hi-Tea Buffet';
else if (/dinner|buffet/i.test(packageName)) category = 'Dinner Buffet';
else if (/pool|gym|swim/i.test(packageName)) category = 'Pool/Gym';
else if (/wedding|shaadi|shadi|nikah|walima|mehndi/i.test(packageName)) category = 'Wedding';
else if (/room|accommodation|suite/i.test(packageName)) category = 'Rooms';
else if (/movie\s*night|auditorium/i.test(packageName)) category = 'Auditorium / Movie Night + Hi-Tea';
else if (/a\s*la\s*carte|alacarte|restaurant|table/i.test(packageName)) category = '\u00c0 la carte / Restaurant Reservation';
else if (/corporate|conference|meeting/i.test(packageName)) category = 'Corporate';
else throw new Error('Choose a configured booking category from the live CRM menu.');
}
if (category === 'Wedding Package') category = 'Wedding';
if (category === 'A la carte / Restaurant Reservation') category = '\u00c0 la carte / Restaurant Reservation';

const date = String(order.date || '').slice(0, 10);
const parsedDate = new Date(date + 'T00:00:00.000Z');
if (!/^\d{4}-\d{2}-\d{2}$/.test(date) || Number.isNaN(parsedDate.getTime()) || parsedDate.toISOString().slice(0, 10) !== date) throw new Error('Check-in date must be a valid YYYY-MM-DD date.');
const persons = Number(order.persons);
if (!Number.isInteger(persons) || persons < 1) throw new Error('Guest count must be a positive whole number.');
if (category === 'Rooms') {
  const checkOutDate = String(order.checkOutDate || '').slice(0, 10);
  const parsedCheckOut = new Date(checkOutDate + 'T00:00:00.000Z');
  if (!/^\d{4}-\d{2}-\d{2}$/.test(checkOutDate) || Number.isNaN(parsedCheckOut.getTime()) || parsedCheckOut.toISOString().slice(0, 10) !== checkOutDate || checkOutDate <= date) throw new Error('Room check-out must be a valid date after check-in.');
  if (!/^[a-f0-9]{24}$/i.test(String(order.roomTypeId || ''))) throw new Error('Choose a configured room type from the live CRM room list.');
  const rooms = Number(order.numberOfRooms || 1);
  if (!Number.isInteger(rooms) || rooms < 1 || rooms > 100) throw new Error('Room count must be a whole number from 1 to 100.');
  const query = new URLSearchParams({ restaurantId: 'restaurant-1', checkInDate: date, checkOutDate, roomTypeId: String(order.roomTypeId), rooms: String(rooms), guests: String(persons) });
  return [{ json: { ...booking, availabilityUrl: 'https://magenta-yak-337378.hostingersite.com/api/rooms/availability/check?' + query } }];
}
const timeMatch = String(order.time || '').trim().match(/^(\d{1,2})(?::(\d{2}))?\s*(AM|PM)?$/i);
if (!timeMatch) throw new Error('Booking time must be a valid time such as 7:00 PM.');
let hour = Number(timeMatch[1]);
const minute = Number(timeMatch[2] || 0);
if (minute > 59 || hour > 23 || (timeMatch[3] && (hour < 1 || hour > 12))) throw new Error('Booking time is invalid.');
if (timeMatch[3]) hour = hour % 12 + (timeMatch[3].toUpperCase() === 'PM' ? 12 : 0);
const time = ('0' + hour).slice(-2) + ':' + ('0' + minute).slice(-2);
if (category === 'Corporate') return [{ json: { ...booking, availabilityNotRequired: true } }];
const query = new URLSearchParams({ restaurantId: 'restaurant-1', date, time, persons: String(persons), category });
return [{ json: { ...booking, availabilityUrl: 'https://magenta-yak-337378.hostingersite.com/api/slots/availability?' + query } }];

