 ? { greeting:'Dear', pending:'Aapki booking request mil gayi hai. Yeh abhi pending hai, confirm nahi hui. Advance payment aur verification ke baad hi booking confirm hogi.', ref:'Booking reference', package:'Package', date:'Date', time:'Time', rooms:'Rooms', roomType:'Room type', checkout:'Check-out', guests:'Guests', total:'Kul raqam', advance:'20% advance', bank:'Bank', title:'Account title', account:'Account number', iban:'IBAN', pay:'Neeche di hui company payment details par 20% advance jama karein. Payment ke baad screenshot isi WhatsApp par bhej dein. Hamari team verification ke baad final booking confirmation bhejegi.', thanks:'Shukriya' }
 : { greeting:'Dear', pending:'We received your booking request. It is PENDING and is not confirmed. The booking will be confirmed only after the advance is paid and verified.', ref:'Booking reference', package:'Package', date:'Date', time:'Time', rooms:'Rooms', roomType:'Room type', checkout:'Check-out', guests:'Guests', total:'Total', advance:'20% advance', bank:'Bank', title:'Account title', account:'Account number', iban:'IBAN', pay:'Please pay the 20% advance using the company payment details below, then send the payment screenshot here on WhatsApp. Our team will send the final booking confirmation after verification.', thanks:'Thank you' };
const details = b.roomType
 ? '*' + labels.roomType + '*: ' + b.roomType + '
*' + labels.rooms + '*: ' + b.numberOfRooms + '
*' + labels.checkout + '*: ' + checkout
 : '*' + labels.time + '*: ' + b.bookingTime;
return labels.greeting + ' ' + b.customerName + ',

' + labels.pending + '

*' + labels.ref + '*: ' + b._id + '
*' + labels.package + '*: ' + b.package + '
*' + labels.date + '*: ' + date + '
' + details + '
*' + labels.guests + '*: ' + b.numberOfPersons + '
*' + labels.total + '*: Rs ' + Number(b.totalAmount).toLocaleString('en-PK') + '
*' + labels.advance + '*: Rs ' + Number(b.advanceAmount).toLocaleString('en-PK') + '

*' + labels.bank + '*: ' + payment.bankName + '
*' + labels.title + '*: ' + payment.accountTitle + '
*' + labels.account + '*: ' + payment.accountNumber + '
*' + labels.iban + '*: ' + payment.iban + '

' + labels.pay + '

' + labels.thanks + ', Hotel d'GATES.';
})() }}

