let output = $('AI Agent').first().json.output || '';
output = output.replace(/\*\*\*SEND_HITEA_IMAGES\*\*\*/g, '').trim();
return [{ json: { output, category: 'Hi-Tea Buffet', fromNumber: $('Edit Fields3').first().json.fromNumber } }];

const source = $input.first().json;
const response = $('Get current CRM menus').first().json;
const menus = Array.isArray(response.data) ? response.data : [];
const menu = menus.find((item) => item.category === source.category && item.isActive !== false);
if (!menu) return [];
const media = menu.media || {};
const assets = [
  ...(media.imageUrls || []).map((url) => ({ type: 'image', url, caption: menu.captionAfterImage || '' })),
  ...(media.pdfUrls || []).map((url) => ({ type: 'document', url, filename: url.split('/').pop().split('?')[0] || 'menu.pdf' })),
  ...(media.videoUrl ? [{ type: 'video', url: media.videoUrl }] : []),
  ...(media.voiceNoteUrl ? [{ type: 'audio', url: media.voiceNoteUrl }] : []),
];
return assets
  .filter((asset) => typeof asset.url === 'string' && /^https:\/\//i.test(asset.url))
  .map((asset) => ({ json: { ...asset, to: source.fromNumber } }));

let output = $input.first().json.output || '';
output = output.replace(/\*\*\*SEND_DINNER_IMAGES\*\*\*/g, '').trim();
return [{ json: { output, category: 'Dinner Buffet', fromNumber: $('Edit Fields3').first().json.fromNumber } }];

let output = $input.first().json.output || '';
output = output.replace(/\*\*\*SEND_WEDDING_IMAGES\*\*\*/g, '').trim();
return [{ json: { output, category: 'Wedding Package', fromNumber: $('Edit Fields3').first().json.fromNumber } }];

let output = $input.first().json.output || '';
output = output.replace(/\*\*\*SEND_POOL_IMAGES\*\*\*/g, '').trim();
return [{ json: { output, category: 'Pool/Gym', fromNumber: $('Edit Fields3').first().json.fromNumber } }];

const raw = String($input.first().json.output || '').replace(/\x60\x60\x60(?:json)?/gi, '').trim();
const result = JSON.parse(raw);
if (result.action !== 'create_reminder' || !result.reminder || !result.reminder.reason) throw new Error('AI follow-up reminder output is incomplete.');
const event = $('Edit Fields').first().json;
const message = event.messages?.[0] || {};
const receivedAt = new Date(Number(message.timestamp) * 1000);
if (!message.id || Number.isNaN(receivedAt.getTime())) throw new Error('WhatsApp message ID or timestamp is missing.');
return [{ json: { restaurantId: 'restaurant-1', fromNumber: $('Edit Fields3').first().json.fromNumber, customerName: String(result.customer?.name || event.contacts?.[0]?.profile?.name || '').trim(), reason: result.reminder.reason, customerMessage: String(result.reminder.customerMessage || $('Edit Fields3').first().json.userMessage || '').trim(), receivedAt: receivedAt.toISOString(), sourceMessageId: message.id, reply: String(result.reply || '').trim() } }];
